from __future__ import annotations

from pathlib import Path

from g4usim_gui.models.run_model import RunSettings


def write_run_macro(path: str | Path, run: RunSettings) -> None:
    """Write a short macro that relies on generated main.ini for configuration."""
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    lines = [
        "# Generated by G4UniversalSim PySide6 Runner.",
        "/control/verbose 1",
        "/run/verbose 1",
        "/event/verbose 0",
        "/tracking/verbose 0",
        "/run/initialize",
    ]
    if not run.dry_run and run.beam_on > 0:
        lines.append(f"/run/beamOn {run.beam_on}")
    target.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
